    sse_encode_opt_box_autoadd_song_view(self.current, serializer);
    sse_encode_list_song_view(self.user, serializer);
    sse_encode_list_song_view(self.autoplay, serializer);
    sse_encode_String(self.repeat, serializer);
  }

